def has_pair(nums, target):
    left = 0
    right = len(nums) - 1
    while left < right:
        total = nums[left] + nums[right]
        if total == target:
            return True
        if total < target:
            left += 1
        else:
            right -= 1
    return False

java.code:
static boolean hasPair(int[] nums, int target) {
    int left = 0;
    int right = nums.length - 1;
    while (left < right) {
        int total = nums[left] + nums[right];
        if (total == target) return true;
        if (total < target) left++;
        else right--;
    }
    return false;
}

